package cn.campus.schedule;

import android.app.*;
import android.content.ClipData;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.util.*;
import org.json.*;

/** Daily presentation metadata lives on the original record and synchronizes with it. */
final class DayPlanning {
    static final String[] MODES={"all","morning","afternoon","evening","time"},NAMES={"全天","上午","下午","晚上","具体时间"};
    static String kind(MainActivity.Entry e){return e.course?"courses":e.mood?"moods":"events";}
    static String key(MainActivity.Entry e){return (e.course||e.mood?"":e.source.optString("occurrence",e.source.optString("date")))+"@"+(e.childId.isEmpty()?"self":e.childId);}
    static String identity(MainActivity.Entry e){return kind(e)+":"+e.source.optString("id")+":"+key(e);}
    static JSONObject record(JSONObject data,MainActivity.Entry e){JSONArray list=data.optJSONArray(kind(e));if(list!=null)for(int i=0;i<list.length();i++)if(list.optJSONObject(i).optString("id").equals(e.source.optString("id")))return list.optJSONObject(i);return null;}
    static JSONObject plan(JSONObject data,MainActivity.Entry e,LocalDate day){JSONObject r=record(data,e),all=r==null?null:r.optJSONObject("agendaPlans"),d=all==null?null:all.optJSONObject(day.toString()),p=d==null?null:d.optJSONObject(key(e));return p==null?new JSONObject():p;}
    static void put(JSONObject data,MainActivity.Entry e,LocalDate day,JSONObject changes){JSONObject r=record(data,e);if(r==null)throw new IllegalArgumentException("安排已不存在");JSONObject all=r.optJSONObject("agendaPlans");if(all==null){all=new JSONObject();AgendaFeatures.put(r,"agendaPlans",all);}JSONObject d=all.optJSONObject(day.toString());if(d==null){d=new JSONObject();AgendaFeatures.put(all,day.toString(),d);}JSONObject p=d.optJSONObject(key(e));if(p==null){p=new JSONObject();AgendaFeatures.put(d,key(e),p);}final JSONObject target=p;changes.keys().forEachRemaining(k->AgendaFeatures.put(target,k,changes.opt(k)));}
    static MainActivity.Entry copy(MainActivity.Entry e){MainActivity.Entry n=AgendaItems.task(e.source);n.continuous=false;n.childId=e.childId;n.title=e.title;n.note=e.note;n.done=e.done;return n;}
    static void apply(MainActivity.Entry e,JSONObject p){String mode=p.optString("section");if(mode.isEmpty())return;int n=Arrays.asList(MODES).indexOf(mode);if(n<0)return;e.allDay=n==0;e.minute=n==0?-1:n==4?ScheduleRules.minutes(p.optString("time")):n==1?0:n==2?720:1080;e.time=n==4?p.optString("time"):NAMES[n];}
    static List<MainActivity.Entry> arrange(JSONObject data,List<MainActivity.Entry> input,LocalDate day){List<MainActivity.Entry> out=new ArrayList<>();for(MainActivity.Entry e:input){JSONObject p=plan(data,e,day);if(e.continuous&&!p.optString("section").isEmpty()){MainActivity.Entry daily=copy(e);apply(daily,p);out.add(daily);}if(!e.continuous)apply(e,p);out.add(e);}out.sort(Comparator.comparing((MainActivity.Entry e)->e.done).thenComparingInt(e->DaySections.group(e.allDay,e.minute)).thenComparingDouble(e->plan(data,e,day).optDouble("order",e.minute*1024.0)).thenComparing(e->e.title));return out;}
    static void edit(MainActivity a,MainActivity.Entry e){LinearLayout form=a.form();Spinner section=new Spinner(a);section.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,NAMES));section.setContentDescription("安排时段");JSONObject p=plan(a.data,e,a.selected);int n=Arrays.asList(MODES).indexOf(p.optString("section","all"));section.setSelection(Math.max(0,n));form.addView(section);EditText time=a.field(form,"具体时间（HH:mm）",p.optString("time","14:00"));a.dialog("安排到当天 · "+e.title,form,()->{String mode=MODES[section.getSelectedItemPosition()],at=time.getText().toString().trim();if(mode.equals("time"))try{ScheduleRules.minutes(at);}catch(Exception ex){throw new IllegalArgumentException("请输入正确的具体时间");}JSONObject next=a.copy();put(next,e,a.selected,AiProtocol.obj("section",mode,"time",mode.equals("time")?at:""));if(!a.persist(next))throw new IllegalArgumentException("保存失败");}).show();}
    static void mood(MainActivity a,MainActivity.Entry e){MainActivity.Entry parent=AgendaItems.task(e.source);parent.title=e.source.optString("title");a.features.mood(null,parent,true);}
    static void drag(MainActivity a,MainActivity.Entry e,LinearLayout card){if(e.done||e.continuous||e.progress)return;TextView handle=a.action("⠿ 拖动排序",()->{});handle.setTextSize(12);handle.setContentDescription("拖动排序："+e.title);handle.setOnLongClickListener(v->{v.startDragAndDrop(ClipData.newPlainText("agenda",identity(e)),new View.DragShadowBuilder(card),e,0);return true;});card.addView(handle,0);card.setOnDragListener((v,event)->{if(!(event.getLocalState() instanceof MainActivity.Entry))return false;MainActivity.Entry from=(MainActivity.Entry)event.getLocalState();if(event.getAction()==DragEvent.ACTION_DRAG_STARTED)return DaySections.group(from.allDay,from.minute)==DaySections.group(e.allDay,e.minute);if(event.getAction()==DragEvent.ACTION_DROP){List<MainActivity.Entry> rows=new ArrayList<>();for(MainActivity.Entry row:AgendaItems.build(a.data,a.selected,LocalDateTime.now()))if(!row.done&&!row.continuous&&!row.progress&&DaySections.group(row.allDay,row.minute)==DaySections.group(e.allDay,e.minute))rows.add(row);int start=-1,end=-1;for(int i=0;i<rows.size();i++){if(identity(rows.get(i)).equals(identity(from)))start=i;if(identity(rows.get(i)).equals(identity(e)))end=i;}if(start>=0&&end>=0&&start!=end){rows.add(end,rows.remove(start));JSONObject next=a.copy();for(int i=0;i<rows.size();i++)put(next,rows.get(i),a.selected,AiProtocol.obj("order",i*1024));if(a.persist(next))a.render();}return true;}return true;});}
}
